export function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export function arrayBufferToBase64(buffer: ArrayBuffer): string {
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function pcmToWav(pcmData: Float32Array, sampleRate: number): ArrayBuffer {
  const numChannels = 1;
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const byteRate = sampleRate * blockAlign;
  const dataSize = pcmData.length * bytesPerSample;
  const buffer = new ArrayBuffer(44 + dataSize);
  const view = new DataView(buffer);

  // RIFF chunk
  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + dataSize, true);
  writeString(view, 8, 'WAVE');

  // fmt sub-chunk
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true); // PCM
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, byteRate, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);

  // data sub-chunk
  writeString(view, 36, 'data');
  view.setUint32(40, dataSize, true);

  // Write PCM samples
  let offset = 44;
  for (let i = 0; i < pcmData.length; i++) {
    const s = Math.max(-1, Math.min(1, pcmData[i]));
    view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7FFF, true);
    offset += 2;
  }

  return buffer;
}

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

// Low-level PCM converters for Live API
export function float32ToInt16(float32: Float32Array): Int16Array {
  const int16 = new Int16Array(float32.length);
  for (let i = 0; i < float32.length; i++) {
    const s = Math.max(-1, Math.min(1, float32[i]));
    int16[i] = s < 0 ? s * 0x8000 : s * 0x7FFF;
  }
  return int16;
}

export function int16ToFloat32(int16: Int16Array): Float32Array {
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    float32[i] = int16[i] / 32768.0;
  }
  return float32;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import { GoogleGenAI, GenerateContentResponse, ChatSession, Modality, LiveServerMessage } from "@google/genai";
import { FileAttachment } from "../types";
import { arrayBufferToBase64, decodeAudioData, float32ToInt16 } from "./audioUtils";

const API_KEY = process.env.API_KEY || "";

const ai = new GoogleGenAI({ apiKey: API_KEY });

// System instruction for the Architect
const ARCHITECT_SYSTEM_PROMPT = `You are a high-level Personal Architecture Agent. 
Your goal is to interview the user and analyze their documents to build a "Master Document Personal Information Agent Reference File".
This file will be used by other autonomous agents to understand the user's traits, preferences, history, and goals.
Structure the final output as a clear Markdown document.
When the user uploads images or files, analyze them for traits to add to the Master Document.
Use your advanced reasoning capabilities to infer deeper traits from the conversation.`;

// --- Standard Chat (Gemini 3 Pro) ---

export const createChatSession = async (): Promise<ChatSession> => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: ARCHITECT_SYSTEM_PROMPT,
      thinkingConfig: {
        thinkingBudget: 32768, 
      },
    },
  });
};

export const sendMessageToChat = async (
  chat: ChatSession,
  message: string,
  attachments: FileAttachment[] = []
): Promise<string> => {

  // Format contents
  const parts: any[] = [];

  attachments.forEach(att => {
    parts.push({
      inlineData: {
        mimeType: att.type,
        data: att.data
      }
    });
  });

  parts.push({ text: message });

  const result: GenerateContentResponse = await chat.sendMessage({
    content: { parts }
  });

  return result.text || "";
};

// --- Live API (Gemini 2.5 Flash Audio) ---

export class LiveClient {
  private sessionPromise: Promise<any> | null = null;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private stream: MediaStream | null = null;
  private processor: ScriptProcessorNode | null = null;
  private inputSource: MediaStreamAudioSourceNode | null = null;

  constructor(
    private onOutput: (text: string) => void,
    private onStatus: (status: string) => void
  ) {}

  async connect() {
    this.onStatus("connecting");

    this.inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    this.outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = this.outputAudioContext.createGain();
    outputNode.connect(this.outputAudioContext.destination);

    try {
      this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      this.sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: ARCHITECT_SYSTEM_PROMPT + " Keep responses concise for voice conversation."
        },
        callbacks: {
          onopen: () => {
            this.onStatus("connected");
            this.startAudioInput();
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle Audio Output
             const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
             if (base64Audio && this.outputAudioContext) {
               this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);

               const audioBuffer = await decodeAudioData(
                 new Uint8Array(atob(base64Audio).split('').map(c => c.charCodeAt(0))),
                 this.outputAudioContext,
                 24000,
                 1
               );

               const source = this.outputAudioContext.createBufferSource();
               source.buffer = audioBuffer;
               source.connect(outputNode);
               source.addEventListener('ended', () => {
                 this.sources.delete(source);
               });
               source.start(this.nextStartTime);
               this.nextStartTime += audioBuffer.duration;
               this.sources.add(source);
             }

             // Handle Interruption
             if (message.serverContent?.interrupted) {
               this.sources.forEach(s => s.stop());
               this.sources.clear();
               this.nextStartTime = 0;
             }

             // Simple visual feedback of "talking" could go here via callback
          },
          onclose: () => {
            this.onStatus("disconnected");
          },
          onerror: (e) => {
            console.error(e);
            this.onStatus("error");
          }
        }
      });
    } catch (err) {
      console.error("Failed to connect live client", err);
      this.onStatus("error");
    }
  }

  private startAudioInput() {
    if (!this.inputAudioContext || !this.stream || !this.sessionPromise) return;

    this.inputSource = this.inputAudioContext.createMediaStreamSource(this.stream);
    this.processor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.processor.onaudioprocess = (e) => {
      const inputData = e.inputBuffer.getChannelData(0);

      // Convert Float32 to Int16 PCM
      const pcmInt16 = float32ToInt16(inputData);
      const pcmUint8 = new Uint8Array(pcmInt16.buffer);
      const base64Data = arrayBufferToBase64(pcmUint8.buffer);

      this.sessionPromise!.then(session => {
        session.sendRealtimeInput({
          media: {
            mimeType: 'audio/pcm;rate=16000',
            data: base64Data
          }
        });
      });
    };

    this.inputSource.connect(this.processor);
    this.processor.connect(this.inputAudioContext.destination);
  }

  async disconnect() {
    if (this.sessionPromise) {
      const session = await this.sessionPromise;
      session.close();
    }

    this.stream?.getTracks().forEach(t => t.stop());
    this.processor?.disconnect();
    this.inputSource?.disconnect();
    this.inputAudioContext?.close();
    this.outputAudioContext?.close();

    this.onStatus("disconnected");
  }
}

import React, { useEffect, useRef, useState } from 'react';
import { Mic, MicOff, Radio, Activity, X } from 'lucide-react';
import { LiveClient } from '../services/geminiService';

interface LiveSessionProps {
  isOpen: boolean;
  onClose: () => void;
}

const LiveSession: React.FC<LiveSessionProps> = ({ isOpen, onClose }) => {
  const [status, setStatus] = useState<string>('disconnected');
  const liveClientRef = useRef<LiveClient | null>(null);

  useEffect(() => {
    if (isOpen && !liveClientRef.current) {
      liveClientRef.current = new LiveClient(
        (text) => console.log(text), // Transcription placeholder
        (st) => setStatus(st)
      );
      liveClientRef.current.connect();
    } else if (!isOpen && liveClientRef.current) {
      liveClientRef.current.disconnect();
      liveClientRef.current = null;
    }

    return () => {
      if (liveClientRef.current) {
        liveClientRef.current.disconnect();
        liveClientRef.current = null;
      }
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl w-full max-w-md p-8 flex flex-col items-center shadow-2xl relative">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-400 hover:text-white transition-colors"
        >
          <X size={24} />
        </button>

        <div className="mb-6">
          <div className={`relative w-24 h-24 rounded-full flex items-center justify-center ${status === 'connected' ? 'bg-indigo-500/20 animate-pulse' : 'bg-slate-800'}`}>
             <div className={`absolute inset-0 rounded-full border-2 ${status === 'connected' ? 'border-indigo-400 opacity-50 animate-ping' : 'border-slate-600'}`}></div>
             <Mic size={40} className={status === 'connected' ? 'text-indigo-400' : 'text-slate-500'} />
          </div>
        </div>

        <h2 className="text-2xl font-bold text-white mb-2">Live Interview</h2>
        <p className="text-slate-400 text-center mb-8">
          Gemini 2.5 Native Audio is listening. Speak naturally to build your persona file.
        </p>

        <div className="flex items-center gap-2 mb-4">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-green-500' : 'bg-yellow-500'}`}></span>
          <span className="text-sm font-medium text-slate-300 uppercase tracking-wider">{status}</span>
        </div>

        {status === 'connected' && (
