import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, Image as ImageIcon, Loader2, Bot, User, BrainCircuit } from 'lucide-react';
import { ChatMessage, MessageRole, FileAttachment } from '../types';
import { ChatSession } from '@google/genai';
import { createChatSession, sendMessageToChat } from '../services/geminiService';

interface ChatInterfaceProps {
  onUpdateDocument: (content: string) => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ onUpdateDocument }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [chatSession, setChatSession] = useState<ChatSession | null>(null);
  const [attachments, setAttachments] = useState<FileAttachment[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const initChat = async () => {
      const session = await createChatSession();
      setChatSession(session);

      const initialMsg: ChatMessage = {
        id: 'init',
        role: MessageRole.MODEL,
        text: "Greetings. I am your Personal Architecture Agent. I'm here to help you construct your Master Reference Document. We can discuss your traits, goals, and history, or you can provide reference files (Drive, Gmail logs, etc.) for me to analyze. How shall we begin?",
        timestamp: Date.now()
      };
      setMessages([initialMsg]);
    };
    initChat();
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      Array.from(files).forEach(file => {
        const reader = new FileReader();
        reader.onload = (entry) => {
          const base64 = (entry.target?.result as string).split(',')[1];
          setAttachments(prev => [...prev, {
            name: file.name,
            type: file.type,
            data: base64
          }]);
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && attachments.length === 0) || !chatSession || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text: inputValue,
      timestamp: Date.now(),
      attachments: [...attachments]
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setAttachments([]);
    setIsLoading(true);

    try {
      // Simulate "Thinking" state visually
      setMessages(prev => [...prev, { id: 'thinking', role: MessageRole.MODEL, text: '', timestamp: Date.now(), isThinking: true }]);

      const responseText = await sendMessageToChat(chatSession, userMsg.text, userMsg.attachments);

      // Remove thinking bubble and add real response
      setMessages(prev => prev.filter(m => m.id !== 'thinking'));

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, modelMsg]);

      // Heuristic: Check if response contains markdown code block which might be the doc update
      // In a real app, we'd use function calling to explicitly update the doc.
      // Here we assume the agent might output the doc in a block if asked.
      if (responseText.includes("# Master Reference Document") || responseText.includes("## Traits")) {
         onUpdateDocument(responseText);
      }

    } catch (error) {
      console.error("Chat error", error);
      setMessages(prev => prev.filter(m => m.id !== 'thinking'));
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: MessageRole.MODEL,
        text: "I encountered an error processing that request. Please try again.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-r border-slate-700">
      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
            }`}>
              {/* Header */}
              <div className="flex items-center gap-2 mb-2 opacity-70 text-xs uppercase tracking-wide font-semibold">
                {msg.role === MessageRole.USER ? <User size={12} /> : <Bot size={12} />}
                <span>{msg.role}</span>
              </div>

              {/* Attachments */}
              {msg.attachments && msg.attachments.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {msg.attachments.map((att, idx) => (
                    <div key={idx} className="bg-black/30 text-xs px-2 py-1 rounded flex items-center gap-1">
                      <ImageIcon size={10} /> {att.name}
                    </div>
                  ))}
                </div>
              )}

              {/* Text */}
              {msg.isThinking ? (
                <div className="flex items-center gap-2 text-indigo-300 animate-pulse">
                  <BrainCircuit size={16} />
                  <span className="text-sm font-medium">Reasoning with Gemini 3 Pro...</span>
                </div>
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-sm">
                  {msg.text}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-slate-900 border-t border-slate-700">
        {attachments.length > 0 && (
          <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
             {attachments.map((att, idx) => (
               <div key={idx} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 flex items-center gap-2 text-xs text-slate-300">
                  <ImageIcon size={12} />
                  <span className="truncate max-w-[100px]">{att.name}</span>
                  <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="hover:text-white">×</button>
               </div>
             ))}
          </div>
        )}
        <div className="flex items-center gap-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-full transition-colors"
            title="Upload Image/File"
          >
            <Paperclip size={20} />
          </button>
          <input 
            type="file" 
            multiple 
            accept="image/*,application/pdf,text/*"
            ref={fileInputRef}
            className="hidden"
            onChange={handleFileUpload}
          />

          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type your response..."
            className="flex-1 bg-slate-800 text-white placeholder-slate-500 rounded-full px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 border border-slate-700"
            disabled={isLoading}
          />

          <button 
            onClick={handleSend}
            disabled={isLoading || (!inputValue.trim() && attachments.length === 0)}
            className={`p-3 rounded-full transition-all ${
              isLoading || (!inputValue.trim() && attachments.length === 0)
                ? 'bg-slate-800 text-slate-600' 
                : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20'
            }`}
          >
            {isLoading ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React from 'react';
import { FileText, Download, Copy, RefreshCw } from 'lucide-react';

interface DocumentViewerProps {
  content: string;
}

const DocumentViewer: React.FC<DocumentViewerProps> = ({ content }) => {
  const handleCopy = () => {
    navigator.clipboard.writeText(content);
  };

  const handleDownload = () => {
    const blob = new Blob([content], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Master_Reference_Document.md';
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="flex flex-col h-full bg-slate-950">
      {/* Header */}
      <div className="h-14 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-sm">
        <div className="flex items-center gap-2 text-indigo-400 font-semibold">
          <FileText size={18} />
          <span>Master Document Preview</span>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={handleCopy}
            className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors text-xs flex items-center gap-1"
          >
            <Copy size={14} /> Copy
          </button>
          <button 
            onClick={handleDownload}
            className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors text-xs flex items-center gap-1"
          >
            <Download size={14} /> Export
          </button>
        </div>
      </div>

      {/* Document Content */}
      <div className="flex-1 overflow-y-auto p-8">
        {content ? (
          <div className="prose prose-invert prose-slate max-w-none">
            {/* Simple Markdown Rendering - in a real app use react-markdown */}
            <div className="whitespace-pre-wrap font-mono text-sm text-slate-300 leading-relaxed">
              {content}
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-slate-600 gap-4">
            <RefreshCw size={48} className="opacity-20" />
            <p className="text-sm">The agent is compiling your document...</p>
            <p className="text-xs max-w-xs text-center">Chat with the agent or use the Live Interview feature to populate this document.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DocumentViewer;

import React, { useState } from 'react';
import ChatInterface from './components/ChatInterface';
import DocumentViewer from './components/DocumentViewer';
import LiveSession from './components/LiveSession';
import { Mic, Layout, Terminal } from 'lucide-react';

const App: React.FC = () => {
  const [documentContent, setDocumentContent] = useState<string>('');
  const [isLiveOpen, setIsLiveOpen] = useState(false);

  // Function to merge new content into the document 
  // (In a real implementation, the LLM would likely return the whole updated doc or diffs)
  const handleUpdateDocument = (newContent: string) => {
    // If the new content looks like a full document, replace it.
    // Otherwise, append it (simplistic logic for demo).
    if (newContent.startsWith('# ')) {
      setDocumentContent(newContent);
    } else {
      setDocumentContent(prev => prev + '\n\n' + newContent);
    }
  };

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-200 overflow-hidden">
