interface LiveSessionProps {
  isOpen: boolean;
  onClose: (transcript?: string) => void;
}

const LiveSession: React.FC<LiveSessionProps> = ({ isOpen, onClose }) => {
  const [status, setStatus] = useState<string>('disconnected');
  const [transcript, setTranscript] = useState<string>('');
  const liveClientRef = useRef<LiveClient | null>(null);

  useEffect(() => {
    if (isOpen) {
      setTranscript(''); // Reset transcript on open
      if (!liveClientRef.current) {
        liveClientRef.current = new LiveClient(
          (text) => console.log(text),
          (newText) => setTranscript(prev => prev + newText),
          (st) => setStatus(st)
        );
        liveClientRef.current.connect();
      }
    } else {
      // Cleanup happens in handleClose or unmount
    }

    return () => {
      if (liveClientRef.current) {
        liveClientRef.current.disconnect();
        liveClientRef.current = null;
      }
    };
  }, [isOpen]);

  const handleClose = () => {
    if (liveClientRef.current) {
      liveClientRef.current.disconnect();
      liveClientRef.current = null;
    }
    onClose(transcript); // Pass transcript back to App
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl w-full max-w-md p-8 flex flex-col items-center shadow-2xl relative">
        <button 
          onClick={handleClose}
          className="absolute top-4 right-4 text-slate-400 hover:text-white transition-colors"
        >
          <X size={24} />
        </button>

        <div className="mb-6">
          <div className={`relative w-24 h-24 rounded-full flex items-center justify-center ${status === 'connected' ? 'bg-indigo-500/20 animate-pulse' : 'bg-slate-800'}`}>
             <div className={`absolute inset-0 rounded-full border-2 ${status === 'connected' ? 'border-indigo-400 opacity-50 animate-ping' : 'border-slate-600'}`}></div>
             <Mic size={40} className={status === 'connected' ? 'text-indigo-400' : 'text-slate-500'} />
          </div>
        </div>

        <h2 className="text-2xl font-bold text-white mb-2">Live Interview</h2>
        <p className="text-slate-400 text-center mb-8">
          Gemini 2.5 is listening. Speak naturally to build your persona file.
        </p>

        <div className="flex items-center gap-2 mb-4">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-green-500' : 'bg-yellow-500'}`}></span>
          <span className="text-sm font-medium text-slate-300 uppercase tracking-wider">{status}</span>
        </div>

        {status === 'connected' && (
           <div className="h-12 flex items-center gap-1 mb-4">
             {[...Array(5)].map((_, i) => (
               <div 
                 key={i}
