import { FileAttachment } from "../types";

// Configuration from environment variables
// Note: In a real deployment, ensure these are set in your build environment
const CLIENT_ID = process.env.GOOGLE_CLIENT_ID || '';
const API_KEY = process.env.GOOGLE_API_KEY || ''; // Needs Drive API & Picker API enabled
const APP_ID = process.env.GOOGLE_APP_ID || ''; // Project Number
const SCOPES = 'https://www.googleapis.com/auth/drive.readonly';

let tokenClient: any;
let accessToken: string | null = null;
let pickerInited = false;
let gisInited = false;

export interface DriveServiceConfig {
  onAuthChange: (isInited: boolean) => void;
}

export const initDriveApi = (config: DriveServiceConfig) => {
  const gapi = (window as any).gapi;
  const google = (window as any).google;

  if (!gapi || !google) return; // Wait for scripts to load

  // Load GAPI Picker
  gapi.load('client:picker', async () => {
    await gapi.client.load('https://www.googleapis.com/discovery/v1/apis/drive/v3/rest');
    pickerInited = true;
    checkInit(config);
  });

  // Init GIS Token Client
  tokenClient = google.accounts.oauth2.initTokenClient({
    client_id: CLIENT_ID,
    scope: SCOPES,
    callback: (tokenResponse: any) => {
      accessToken = tokenResponse.access_token;
    },
  });
  gisInited = true;
  checkInit(config);
};

const checkInit = (config: DriveServiceConfig) => {
  if (pickerInited && gisInited) {
    config.onAuthChange(true);
  }
};

export const requestAccessToken = (): Promise<string> => {
  return new Promise((resolve, reject) => {
    if (accessToken) {
      resolve(accessToken);
      return;
    }

    const google = (window as any).google;
    tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: CLIENT_ID,
      scope: SCOPES,
      callback: (tokenResponse: any) => {
        if (tokenResponse.error !== undefined) {
          reject(tokenResponse);
        }
        accessToken = tokenResponse.access_token;
        resolve(accessToken);
      },
    });

    // Trigger the flow
    tokenClient.requestAccessToken({ prompt: 'consent' });
  });
};

export const openPicker = async (): Promise<any[]> => {
  if (!accessToken) {
    await requestAccessToken();
  }

  return new Promise((resolve, reject) => {
    const google = (window as any).google;
    const ViewId = google.picker.ViewId;

    const picker = new google.picker.PickerBuilder()
      .enableFeature(google.picker.Feature.NAV_HIDDEN)
      .enableFeature(google.picker.Feature.MULTISELECT_ENABLED)
      .setAppId(APP_ID)
      .setOAuthToken(accessToken!)
      .addView(new google.picker.DocsView(ViewId.DOCS))
      .addView(new google.picker.DocsView(ViewId.FOLDERS))
      .setDeveloperKey(API_KEY)
      .setCallback((data: any) => {
        if (data.action === google.picker.Action.PICKED) {
          resolve(data.docs);
        } else if (data.action === google.picker.Action.CANCEL) {
          resolve([]);
        }
      })
      .build();
    picker.setVisible(true);
  });
};

// Recursive function to get all files from folders
const expandFolders = async (items: any[]): Promise<any[]> => {
  const gapi = (window as any).gapi;
  let allFiles: any[] = [];

  for (const item of items) {
    if (item.mimeType === 'application/vnd.google-apps.folder') {
      // List children
      try {
        const response = await gapi.client.drive.files.list({
          q: `'${item.id}' in parents and trashed = false`,
          fields: 'files(id, name, mimeType)',
          pageSize: 100 // Cap to prevent overload
        });
        const children = response.result.files;
        // Recursively expand children (shallow for now to avoid complexity)
        const expandedChildren = await expandFolders(children);
        allFiles = [...allFiles, ...expandedChildren];
      } catch (err) {
        console.error("Error expanding folder", item.name, err);
      }
    } else {
      allFiles.push(item);
    }
  }
  return allFiles;
};

export const downloadDriveFiles = async (pickedItems: any[]): Promise<FileAttachment[]> => {
  const gapi = (window as any).gapi;
  if (!gapi.client.drive) {
    throw new Error("Drive API not loaded");
  }

  // 1. Flatten folders
  const filesToProcess = await expandFolders(pickedItems);
  const attachments: FileAttachment[] = [];

  // 2. Process each file
  for (const file of filesToProcess) {
    try {
      let result: any;
      let mimeType = file.mimeType;
      let finalMimeType = file.mimeType;

      // Logic for Google Docs Export
      if (file.mimeType === 'application/vnd.google-apps.document') {
        finalMimeType = 'text/plain';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/plain'
        });
      } else if (file.mimeType === 'application/vnd.google-apps.spreadsheet') {
        finalMimeType = 'text/csv';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/csv'
        });
      } else if (file.mimeType === 'application/vnd.google-apps.presentation') {
        finalMimeType = 'text/plain';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/plain'
        });
      } else {
        // Regular file download
        // Note: 'alt=media' downloads binary
        // We need to fetch this using raw fetch to get Blob easily if gapi doesn't return body nicely
        // But gapi list/get usually returns body string for text. 
        // For binary (PDF/Images), we need proper handling.

        const token = gapi.client.getToken().access_token;
        const resp = await fetch(`https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        const blob = await resp.blob();
        const base64 = await blobToBase64(blob);

        attachments.push({
          name: file.name,
          type: file.mimeType,
          data: base64
        });
        continue;
      }

      // Handle Exported Text Content
      // result.body contains the text
      const textContent = result.body;
      const base64Content = btoa(unescape(encodeURIComponent(textContent))); // UTF-8 safe base64

      attachments.push({
        name: file.name + (finalMimeType === 'text/plain' ? '.txt' : '.csv'),
        type: finalMimeType,
        data: base64Content
      });

    } catch (e) {
      console.error(`Failed to download/export file ${file.name}`, e);
    }
  }

  return attachments;
};

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      // remove data:.*;base64, prefix
      resolve(result.split(',')[1]); 
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

import React, { useState, useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import { Send, Paperclip, Image as ImageIcon, Loader2, Bot, User, BrainCircuit, FileJson, HardDrive } from 'lucide-react';
import { ChatMessage, MessageRole, FileAttachment } from '../types';
import { ChatSession } from '@google/genai';
import { createChatSession, sendMessageToChat, sendToolResponseToChat } from '../services/geminiService';
import { initDriveApi, openPicker, downloadDriveFiles } from '../services/driveService';

interface ChatInterfaceProps {
  onUpdateDocument: (content: string) => void;
}

export interface ChatInterfaceRef {
  injectMessage: (text: string) => void;
}

const ChatInterface = forwardRef<ChatInterfaceRef, ChatInterfaceProps>(({ onUpdateDocument }, ref) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDriveLoading, setIsDriveLoading] = useState(false);
  const [chatSession, setChatSession] = useState<ChatSession | null>(null);
  const [attachments, setAttachments] = useState<FileAttachment[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Initialize Chat
    const initChat = async () => {
      const session = await createChatSession();
      setChatSession(session);

      const initialMsg: ChatMessage = {
        id: 'init',
        role: MessageRole.MODEL,
        text: "Greetings. I am your Personal Architecture Agent. I'm here to help you construct your Master Reference Document.\n\nPlease upload relevant files (Trading Logs, Journal Entries, Drive Exports) or simply speak with me to begin analyzing your traits and history.",
        timestamp: Date.now()
      };
      setMessages([initialMsg]);
    };
    initChat();

    // Initialize Drive API
    // Check if window exists to be safe
    if (typeof window !== 'undefined') {
       // Simple retry logic or callback setup
       const interval = setInterval(() => {
         if ((window as any).google && (window as any).gapi) {
            initDriveApi({
              onAuthChange: (inited) => console.log("Drive API Initialized:", inited)
            });
            clearInterval(interval);
         }
       }, 500);
    }
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Expose injectMessage to parent for Live Transcript handover
  useImperativeHandle(ref, () => ({
    injectMessage: (text: string) => {
      setInputValue(text);
    }
  }));

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onload = (entry) => {
          const base64 = (entry.target?.result as string).split(',')[1];
          setAttachments(prev => [...prev, {
            name: file.name,
            type: file.type,
            data: base64
          }]);
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleDriveClick = async () => {
    try {
      setIsDriveLoading(true);
      const pickedDocs = await openPicker();
      if (pickedDocs && pickedDocs.length > 0) {
        setMessages(prev => [...prev, {
          id: 'drive-loading-' + Date.now(),
          role: MessageRole.SYSTEM,
          text: `Processing ${pickedDocs.length} items from Google Drive...`,
          timestamp: Date.now()
        }]);

        const driveAttachments = await downloadDriveFiles(pickedDocs);
        setAttachments(prev => [...prev, ...driveAttachments]);

        setMessages(prev => [...prev, {
          id: 'drive-done-' + Date.now(),
          role: MessageRole.SYSTEM,
          text: `Successfully attached ${driveAttachments.length} files from Drive.`,
          timestamp: Date.now()
        }]);
      }
    } catch (error) {
      console.error("Drive Error", error);
      setMessages(prev => [...prev, {
        id: 'drive-err-' + Date.now(),
        role: MessageRole.SYSTEM,
        text: "Error accessing Google Drive. Please check your credentials or permissions.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsDriveLoading(false);
    }
  };

  const processResponse = async (responseText: string, toolCalls?: any[]) => {
    // 1. Add model text message if present
    if (responseText) {
      const modelMsg: ChatMessage = {
        id: Date.now().toString(),
        role: MessageRole.MODEL,
        text: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, modelMsg]);
    }

    // 2. Handle Tool Calls
    if (toolCalls && toolCalls.length > 0) {
      for (const call of toolCalls) {
        if (call.name === 'updateMasterDocument') {
          // Visual feedback that tool is running
          setMessages(prev => [...prev, {
            id: 'tool-' + Date.now(),
            role: MessageRole.SYSTEM,
            text: "Updating Master Document...",
            timestamp: Date.now()
          }]);

          // Execute UI update
          onUpdateDocument(call.args.content);

          // Send confirmation back to model (important for chat state)
          if (chatSession) {
             await sendToolResponseToChat(chatSession, call.name, { success: true });
          }
        }
      }
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && attachments.length === 0) || !chatSession || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text: inputValue,
      timestamp: Date.now(),
      attachments: [...attachments]
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setAttachments([]);
    setIsLoading(true);

    try {
      setMessages(prev => [...prev, { id: 'thinking', role: MessageRole.MODEL, text: '', timestamp: Date.now(), isThinking: true }]);

      const response = await sendMessageToChat(chatSession, userMsg.text, userMsg.attachments);

      setMessages(prev => prev.filter(m => m.id !== 'thinking'));
      await processResponse(response.text, response.toolCalls);

    } catch (error) {
      console.error("Chat error", error);
      setMessages(prev => prev.filter(m => m.id !== 'thinking'));
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: MessageRole.MODEL,
        text: "I encountered an error processing that request. Please try again.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-r border-slate-700">
      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : msg.role === MessageRole.SYSTEM 
                  ? 'bg-slate-800/50 text-slate-400 text-xs text-center w-full border border-dashed border-slate-700'
                  : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
            }`}>
              {/* Header */}
              {msg.role !== MessageRole.SYSTEM && (
                <div className="flex items-center gap-2 mb-2 opacity-70 text-xs uppercase tracking-wide font-semibold">
                  {msg.role === MessageRole.USER ? <User size={12} /> : <Bot size={12} />}
                  <span>{msg.role}</span>
                </div>
              )}

              {/* Attachments */}
              {msg.attachments && msg.attachments.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {msg.attachments.map((att, idx) => (
                    <div key={idx} className="bg-black/30 text-xs px-2 py-1 rounded flex items-center gap-1">
                      <ImageIcon size={10} /> {att.name}
                    </div>
                  ))}
                </div>
              )}

              {/* Text */}
              {msg.isThinking ? (
                <div className="flex items-center gap-2 text-indigo-300 animate-pulse">
                  <BrainCircuit size={16} />
                  <span className="text-sm font-medium">Reasoning with Gemini 3 Pro...</span>
                </div>
              ) : msg.role === MessageRole.SYSTEM ? (
                <div className="flex items-center justify-center gap-2">
                   <FileJson size={14} /> {msg.text}
                </div>
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-sm">
                  {msg.text}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-slate-900 border-t border-slate-700">
        {attachments.length > 0 && (
          <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
             {attachments.map((att, idx) => (
               <div key={idx} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 flex items-center gap-2 text-xs text-slate-300">
                  <ImageIcon size={12} />
                  <span className="truncate max-w-[100px]">{att.name}</span>
