import { GoogleGenAI, GenerateContentResponse, ChatSession, Modality, LiveServerMessage, FunctionDeclaration, Type, Tool } from "@google/genai";
import { FileAttachment, ToolCallData } from "../types";
import { arrayBufferToBase64, decodeAudioData, float32ToInt16 } from "./audioUtils";

// Safely access environment variables
const getEnvVar = (key: string) => {
  if (typeof process !== 'undefined' && process.env) {
    return process.env[key] || "";
  }
  return "";
};

const API_KEY = getEnvVar("API_KEY");

const ai = new GoogleGenAI({ apiKey: API_KEY });

// System instruction for the Architect
const ARCHITECT_SYSTEM_PROMPT = `You are a high-level Personal Architecture Agent. 
Your goal is to interview the user and analyze their documents to build a "Master Document Personal Information Agent Reference File".
This file will be used by other autonomous agents to understand the user's traits, preferences, history, and goals.

INPUT SOURCES:
- The user may upload text files, PDFs, or images.
- The user may paste content from Google Drive or Gmail exports.
- You may receive transcripts from Live Audio interviews.

OUTPUT:
- You must maintain a comprehensive Markdown document.
- Whenever you gather new significant information, call the "updateMasterDocument" function to save the latest version of the file.
- Do not just print the markdown in the chat; YOU MUST USE THE TOOL to save it.

BEHAVIOR:
- Be proactive. If information is missing (e.g., "What is your risk tolerance for trading?"), ask for it.
- If the user mentions a file (e.g., "Check my trading journal"), ask them to upload it or paste the content.
- Use your advanced reasoning capabilities to infer deeper traits from the conversation.`;

// --- Tool Definitions ---

const updateDocumentTool: FunctionDeclaration = {
  name: "updateMasterDocument",
  description: "Updates the content of the Master Reference Document. Call this whenever you have gathered enough information to create or refine the document sections.",
  parameters: {
    type: Type.OBJECT,
    properties: {
      content: {
        type: Type.STRING,
        description: "The full, updated markdown content of the master document.",
      },
    },
    required: ["content"],
  },
};

const tools: Tool[] = [{ functionDeclarations: [updateDocumentTool] }];

// --- Standard Chat (Gemini 3 Pro) ---

export const createChatSession = async (): Promise<ChatSession> => {
  return ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: ARCHITECT_SYSTEM_PROMPT,
      tools: tools,
      thinkingConfig: {
        thinkingBudget: 32768, 
      },
    },
  });
};

export interface ChatResponse {
  text: string;
  toolCalls?: ToolCallData[];
}

export const sendMessageToChat = async (
  chat: ChatSession,
  message: string,
  attachments: FileAttachment[] = []
): Promise<ChatResponse> => {

  // Format contents
  const parts: any[] = [];

  attachments.forEach(att => {
    parts.push({
      inlineData: {
        mimeType: att.type,
        data: att.data
      }
    });
  });

  parts.push({ text: message });

  const result: GenerateContentResponse = await chat.sendMessage({
    content: { parts }
  });

  const response: ChatResponse = {
    text: result.text || "",
    toolCalls: []
  };

  // Check for function calls
  if (result.functionCalls && result.functionCalls.length > 0) {
    response.toolCalls = result.functionCalls.map(fc => ({
      name: fc.name,
      args: fc.args
    }));
  }

  return response;
};

// Send tool response back to model to maintain context
export const sendToolResponseToChat = async (
  chat: ChatSession,
  toolName: string,
  result: any
): Promise<string> => {
  const response = await chat.sendMessage({
    content: [{
      parts: [
        {
          functionResponse: {
            name: toolName,
            response: { result: result }
          }
        }
      ]
    }]
  });
  return response.text || "";
};

// --- Live API (Gemini 2.5 Flash Audio) ---

export class LiveClient {
  private sessionPromise: Promise<any> | null = null;
  private inputAudioContext: AudioContext | null = null;
  private outputAudioContext: AudioContext | null = null;
  private nextStartTime = 0;
  private sources = new Set<AudioBufferSourceNode>();
  private stream: MediaStream | null = null;
  private processor: ScriptProcessorNode | null = null;
  private inputSource: MediaStreamAudioSourceNode | null = null;

  constructor(
    private onOutput: (text: string) => void, // For logging
    private onTranscript: (text: string) => void, // For collecting transcript
    private onStatus: (status: string) => void
  ) {}

  async connect() {
    this.onStatus("connecting");

    this.inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    this.outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const outputNode = this.outputAudioContext.createGain();
    outputNode.connect(this.outputAudioContext.destination);

    try {
      this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      this.sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {}, // Enable input transcription
          outputAudioTranscription: {}, // Enable output transcription
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction: ARCHITECT_SYSTEM_PROMPT + " Keep responses concise for voice conversation."
        },
        callbacks: {
          onopen: () => {
            this.onStatus("connected");
            this.startAudioInput();
          },
          onmessage: async (message: LiveServerMessage) => {
             // Handle Transcriptions
             if (message.serverContent?.inputTranscription) {
               this.onTranscript("User: " + message.serverContent.inputTranscription.text + "\n");
             }
             if (message.serverContent?.outputTranscription) {
               this.onTranscript("Architect: " + message.serverContent.outputTranscription.text + "\n");
             }

             // Handle Audio Output
             const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
             if (base64Audio && this.outputAudioContext) {
               this.nextStartTime = Math.max(this.nextStartTime, this.outputAudioContext.currentTime);

               const audioBuffer = await decodeAudioData(
                 new Uint8Array(atob(base64Audio).split('').map(c => c.charCodeAt(0))),
                 this.outputAudioContext,
                 24000,
                 1
               );

               const source = this.outputAudioContext.createBufferSource();
               source.buffer = audioBuffer;
               source.connect(outputNode);
               source.addEventListener('ended', () => {
                 this.sources.delete(source);
               });
               source.start(this.nextStartTime);
               this.nextStartTime += audioBuffer.duration;
               this.sources.add(source);
             }

             // Handle Interruption
             if (message.serverContent?.interrupted) {
               this.sources.forEach(s => s.stop());
               this.sources.clear();
               this.nextStartTime = 0;
             }
          },
          onclose: () => {
            this.onStatus("disconnected");
          },
          onerror: (e) => {
            console.error(e);
            this.onStatus("error");
          }
        }
      });
    } catch (err) {
      console.error("Failed to connect live client", err);
      this.onStatus("error");
    }
  }

  private startAudioInput() {
    if (!this.inputAudioContext || !this.stream || !this.sessionPromise) return;

    this.inputSource = this.inputAudioContext.createMediaStreamSource(this.stream);
    this.processor = this.inputAudioContext.createScriptProcessor(4096, 1, 1);

    this.processor.onaudioprocess = (e) => {
      const inputData = e.inputBuffer.getChannelData(0);

      // Convert Float32 to Int16 PCM
      const pcmInt16 = float32ToInt16(inputData);
      const pcmUint8 = new Uint8Array(pcmInt16.buffer);
      const base64Data = arrayBufferToBase64(pcmUint8.buffer);

      this.sessionPromise!.then(session => {
        session.sendRealtimeInput({
          media: {
            mimeType: 'audio/pcm;rate=16000',
            data: base64Data
          }
        });
      });
    };

    this.inputSource.connect(this.processor);
    this.processor.connect(this.inputAudioContext.destination);
  }

  async disconnect() {
    if (this.sessionPromise) {
      const session = await this.sessionPromise;
      session.close();
    }

    this.stream?.getTracks().forEach(t => t.stop());
    this.processor?.disconnect();
    this.inputSource?.disconnect();
    this.inputAudioContext?.close();
    this.outputAudioContext?.close();

    this.onStatus("disconnected");
  }
}

import { FileAttachment } from "../types";

// Safely access environment variables
const getEnvVar = (key: string) => {
  if (typeof process !== 'undefined' && process.env) {
    return process.env[key] || "";
  }
  return "";
};

const CLIENT_ID = getEnvVar("GOOGLE_CLIENT_ID");
const API_KEY = getEnvVar("GOOGLE_API_KEY");
const APP_ID = getEnvVar("GOOGLE_APP_ID");
const SCOPES = 'https://www.googleapis.com/auth/drive.readonly';

let tokenClient: any;
let accessToken: string | null = null;
let pickerInited = false;
let gisInited = false;

export interface DriveServiceConfig {
  onAuthChange: (isInited: boolean) => void;
}

export const initDriveApi = (config: DriveServiceConfig) => {
  // Defensive check for config
  if (!CLIENT_ID || !API_KEY || !APP_ID) {
    console.warn("Google Drive API configuration missing (CLIENT_ID, API_KEY, or APP_ID). Drive features will be disabled.");
    return;
  }

  const gapi = (window as any).gapi;
  const google = (window as any).google;

  if (!gapi || !google || !google.accounts || !google.accounts.oauth2) return;

  try {
    // Load GAPI Picker
    gapi.load('client:picker', async () => {
      try {
        await gapi.client.load('https://www.googleapis.com/discovery/v1/apis/drive/v3/rest');
        pickerInited = true;
        checkInit(config);
      } catch (e) {
        console.error("Failed to load GAPI Drive discovery", e);
      }
    });

    // Init GIS Token Client
    tokenClient = google.accounts.oauth2.initTokenClient({
      client_id: CLIENT_ID,
      scope: SCOPES,
      callback: (tokenResponse: any) => {
        accessToken = tokenResponse.access_token;
      },
    });
    gisInited = true;
    checkInit(config);
  } catch (e) {
    console.error("Error initializing Google APIs", e);
  }
};

const checkInit = (config: DriveServiceConfig) => {
  if (pickerInited && gisInited) {
    config.onAuthChange(true);
  }
};

export const requestAccessToken = (): Promise<string> => {
  return new Promise((resolve, reject) => {
    if (accessToken) {
      resolve(accessToken);
      return;
    }

    if (!tokenClient) {
        // Try to re-init if context allows, otherwise fail
        if (CLIENT_ID && (window as any).google?.accounts?.oauth2) {
             try {
                tokenClient = (window as any).google.accounts.oauth2.initTokenClient({
                    client_id: CLIENT_ID,
                    scope: SCOPES,
                    callback: (tokenResponse: any) => {
                        if (tokenResponse.error !== undefined) {
                            reject(tokenResponse);
                        }
                        accessToken = tokenResponse.access_token;
                        resolve(accessToken);
                    },
                });
             } catch (e) {
                 reject(new Error("Failed to initialize token client: " + e));
                 return;
             }
        } else {
             reject(new Error("Google Identity Services not initialized or configuration missing."));
             return;
        }
    }

    // Trigger the flow
    try {
        if (tokenClient) {
            tokenClient.requestAccessToken({ prompt: 'consent' });
        } else {
            reject(new Error("Token client could not be initialized"));
        }
    } catch (e) {
        reject(e);
    }
  });
};

export const openPicker = async (): Promise<any[]> => {
  if (!accessToken) {
    try {
        await requestAccessToken();
    } catch (e) {
        console.error("Auth failed", e);
        throw e;
    }
  }

  return new Promise((resolve, reject) => {
    const google = (window as any).google;
    if (!google || !google.picker) {
        reject(new Error("Google Picker API not loaded"));
        return;
    }

    try {
        const ViewId = google.picker.ViewId;

        const picker = new google.picker.PickerBuilder()
        .enableFeature(google.picker.Feature.NAV_HIDDEN)
        .enableFeature(google.picker.Feature.MULTISELECT_ENABLED)
        .setAppId(APP_ID)
        .setOAuthToken(accessToken!)
        .addView(new google.picker.DocsView(ViewId.DOCS))
        .addView(new google.picker.DocsView(ViewId.FOLDERS))
        .setDeveloperKey(API_KEY)
        .setCallback((data: any) => {
            if (data.action === google.picker.Action.PICKED) {
            resolve(data.docs);
            } else if (data.action === google.picker.Action.CANCEL) {
            resolve([]);
            }
        })
        .build();
        picker.setVisible(true);
    } catch (e) {
        reject(e);
    }
  });
};

// Recursive function to get all files from folders
const expandFolders = async (items: any[]): Promise<any[]> => {
  const gapi = (window as any).gapi;
  if (!gapi || !gapi.client || !gapi.client.drive) return items;

  let allFiles: any[] = [];

  for (const item of items) {
    if (item.mimeType === 'application/vnd.google-apps.folder') {
      try {
        const response = await gapi.client.drive.files.list({
          q: `'${item.id}' in parents and trashed = false`,
          fields: 'files(id, name, mimeType)',
          pageSize: 100
        });
        const children = response.result.files;
        const expandedChildren = await expandFolders(children);
        allFiles = [...allFiles, ...expandedChildren];
      } catch (err) {
        console.error("Error expanding folder", item.name, err);
      }
    } else {
      allFiles.push(item);
    }
  }
  return allFiles;
};

export const downloadDriveFiles = async (pickedItems: any[]): Promise<FileAttachment[]> => {
  const gapi = (window as any).gapi;
  if (!gapi.client.drive) {
    throw new Error("Drive API not loaded");
  }

  const filesToProcess = await expandFolders(pickedItems);
  const attachments: FileAttachment[] = [];

  for (const file of filesToProcess) {
    try {
      let result: any;
      let finalMimeType = file.mimeType;

      if (file.mimeType === 'application/vnd.google-apps.document') {
        finalMimeType = 'text/plain';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/plain'
        });
      } else if (file.mimeType === 'application/vnd.google-apps.spreadsheet') {
        finalMimeType = 'text/csv';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/csv'
        });
      } else if (file.mimeType === 'application/vnd.google-apps.presentation') {
        finalMimeType = 'text/plain';
        result = await gapi.client.drive.files.export({
          fileId: file.id,
          mimeType: 'text/plain'
        });
      } else {
        const token = gapi.client.getToken().access_token;
        const resp = await fetch(`https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        const blob = await resp.blob();
        const base64 = await blobToBase64(blob);

        attachments.push({
          name: file.name,
          type: file.mimeType,
          data: base64
        });
        continue;
      }

      const textContent = result.body;
      const base64Content = btoa(unescape(encodeURIComponent(textContent)));

      attachments.push({
        name: file.name + (finalMimeType === 'text/plain' ? '.txt' : '.csv'),
        type: finalMimeType,
        data: base64Content
      });

    } catch (e) {
      console.error(`Failed to download/export file ${file.name}`, e);
    }
  }

  return attachments;
};

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      resolve(result.split(',')[1]); 
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

import React, { useState, useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import { Send, Paperclip, Image as ImageIcon, Loader2, Bot, User, BrainCircuit, FileJson, HardDrive } from 'lucide-react';
import { ChatMessage, MessageRole, FileAttachment } from '../types';
import { Chat } from '@google/genai';
import { createChatSession, sendMessageToChat, sendToolResponseToChat } from '../services/geminiService';
import { initDriveApi, openPicker, downloadDriveFiles } from '../services/driveService';

interface ChatInterfaceProps {
  onUpdateDocument: (content: string) => void;
}

export interface ChatInterfaceRef {
  injectMessage: (text: string) => void;
}

const ChatInterface = forwardRef<ChatInterfaceRef, ChatInterfaceProps>(({ onUpdateDocument }, ref) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isDriveLoading, setIsDriveLoading] = useState(false);
  const [chatSession, setChatSession] = useState<Chat | null>(null);
  const [attachments, setAttachments] = useState<FileAttachment[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Initialize Chat
    const initChat = async () => {
      const session = await createChatSession();
      setChatSession(session);

      const initialMsg: ChatMessage = {
        id: 'init',
        role: MessageRole.MODEL,
        text: "Greetings. I am your Personal Architecture Agent. I'm here to help you construct your Master Reference Document.\n\nPlease upload relevant files (Trading Logs, Journal Entries, Drive Exports) or simply speak with me to begin analyzing your traits and history.",
        timestamp: Date.now()
      };
      setMessages([initialMsg]);
    };
    initChat();

    // Initialize Drive API
    // Check if window exists to be safe
    let interval: any;
    if (typeof window !== 'undefined') {
       // Simple retry logic or callback setup
       interval = setInterval(() => {
         const w = window as any;
         // Check for both gapi and google.accounts.oauth2 to be fully loaded
         if (w.google && w.google.accounts && w.google.accounts.oauth2 && w.gapi) {
            try {
              initDriveApi({
                onAuthChange: (inited) => console.log("Drive API Initialized:", inited)
              });
            } catch (err) {
              console.error("Failed to initialize Drive API", err);
            }
            clearInterval(interval);
         }
       }, 500);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Expose injectMessage to parent for Live Transcript handover
  useImperativeHandle(ref, () => ({
    injectMessage: (text: string) => {
      setInputValue(text);
    }
  }));

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onload = (entry) => {
          const base64 = (entry.target?.result as string).split(',')[1];
          setAttachments(prev => [...prev, {
            name: file.name,
            type: file.type,
            data: base64
          }]);
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleDriveClick = async () => {
    try {
      setIsDriveLoading(true);
      const pickedDocs = await openPicker();
      if (pickedDocs && pickedDocs.length > 0) {
        setMessages(prev => [...prev, {
          id: 'drive-loading-' + Date.now(),
          role: MessageRole.SYSTEM,
          text: `Processing ${pickedDocs.length} items from Google Drive...`,
          timestamp: Date.now()
        }]);

        const driveAttachments = await downloadDriveFiles(pickedDocs);
        setAttachments(prev => [...prev, ...driveAttachments]);

        setMessages(prev => [...prev, {
          id: 'drive-done-' + Date.now(),
          role: MessageRole.SYSTEM,
          text: `Successfully attached ${driveAttachments.length} files from Drive.`,
          timestamp: Date.now()
        }]);
      }
    } catch (error: any) {
      console.error("Drive Error", error);
      let errorMsg = "Error accessing Google Drive.";
      if (error?.message?.includes("configuration missing")) {
        errorMsg = "Drive API configuration is missing. Please check your environment variables.";
      } else if (error?.message?.includes("Picker API not loaded")) {
        errorMsg = "Google Picker API failed to load. Please refresh and try again.";
      }

      setMessages(prev => [...prev, {
        id: 'drive-err-' + Date.now(),
        role: MessageRole.SYSTEM,
        text: errorMsg,
        timestamp: Date.now()
      }]);
    } finally {
      setIsDriveLoading(false);
    }
  };

  const processResponse = async (responseText: string, toolCalls?: any[]) => {
    // 1. Add model text message if present
    if (responseText) {
      const modelMsg: ChatMessage = {
        id: Date.now().toString(),
        role: MessageRole.MODEL,
        text: responseText,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, modelMsg]);
    }

    // 2. Handle Tool Calls
    if (toolCalls && toolCalls.length > 0) {
      for (const call of toolCalls) {
        if (call.name === 'updateMasterDocument') {
          // Visual feedback that tool is running
          setMessages(prev => [...prev, {
            id: 'tool-' + Date.now(),
            role: MessageRole.SYSTEM,
            text: "Updating Master Document...",
            timestamp: Date.now()
          }]);

          // Execute UI update
          onUpdateDocument(call.args.content);

          // Send confirmation back to model (important for chat state)
          if (chatSession) {
             await sendToolResponseToChat(chatSession, call.name, { success: true });
          }
        }
      }
    }
  };

  const handleSend = async () => {
    if ((!inputValue.trim() && attachments.length === 0) || !chatSession || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text: inputValue,
      timestamp: Date.now(),
      attachments: [...attachments]
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue('');
    setAttachments([]);
    setIsLoading(true);

    try {
      setMessages(prev => [...prev, { id: 'thinking', role: MessageRole.MODEL, text: '', timestamp: Date.now(), isThinking: true }]);

      const response = await sendMessageToChat(chatSession, userMsg.text, userMsg.attachments);

      setMessages(prev => prev.filter(m => m.id !== 'thinking'));
      await processResponse(response.text, response.toolCalls);

    } catch (error) {
      console.error("Chat error", error);
      setMessages(prev => prev.filter(m => m.id !== 'thinking'));
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: MessageRole.MODEL,
        text: "I encountered an error processing that request. Please try again.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 border-r border-slate-700">
      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === MessageRole.USER ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${
              msg.role === MessageRole.USER 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : msg.role === MessageRole.SYSTEM 
                  ? 'bg-slate-800/50 text-slate-400 text-xs text-center w-full border border-dashed border-slate-700'
                  : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700'
            }`}>
              {/* Header */}
              {msg.role !== MessageRole.SYSTEM && (
                <div className="flex items-center gap-2 mb-2 opacity-70 text-xs uppercase tracking-wide font-semibold">
                  {msg.role === MessageRole.USER ? <User size={12} /> : <Bot size={12} />}
                  <span>{msg.role}</span>
                </div>
              )}

              {/* Attachments */}
              {msg.attachments && msg.attachments.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-3">
                  {msg.attachments.map((att, idx) => (
                    <div key={idx} className="bg-black/30 text-xs px-2 py-1 rounded flex items-center gap-1">
                      <ImageIcon size={10} /> {att.name}
                    </div>
                  ))}
                </div>
              )}

              {/* Text */}
              {msg.isThinking ? (
                <div className="flex items-center gap-2 text-indigo-300 animate-pulse">
                  <BrainCircuit size={16} />
                  <span className="text-sm font-medium">Reasoning with Gemini 3 Pro...</span>
                </div>
              ) : msg.role === MessageRole.SYSTEM ? (
                <div className="flex items-center justify-center gap-2">
                   <FileJson size={14} /> {msg.text}
                </div>
              ) : (
                <div className="whitespace-pre-wrap leading-relaxed text-sm">
                  {msg.text}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-4 bg-slate-900 border-t border-slate-700">
        {attachments.length > 0 && (
          <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
             {attachments.map((att, idx) => (
               <div key={idx} className="bg-slate-800 border border-slate-600 rounded px-2 py-1 flex items-center gap-2 text-xs text-slate-300">
                  <ImageIcon size={12} />
                  <span className="truncate max-w-[100px]">{att.name}</span>
                  <button onClick={() => setAttachments(prev => prev.filter((_, i) => i !== idx))} className="hover:text-white">×</button>
               </div>
             ))}
          </div>
        )}
        <div className="flex items-center gap-2">
          {/* Drive Button */}
          <button 
            onClick={handleDriveClick}
            disabled={isDriveLoading}
            className={`p-3 rounded-full transition-colors ${isDriveLoading ? 'bg-slate-800 text-slate-600' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            title="Import from Google Drive"
          >
            {isDriveLoading ? <Loader2 size={20} className="animate-spin" /> : <HardDrive size={20} />}
          </button>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-3 text-slate-400 hover:text-white hover:bg-slate-800 rounded-full transition-colors"
            title="Upload Image/File"
          >
            <Paperclip size={20} />
          </button>
          <input 
            type="file" 
            multiple 
            accept="image/*,application/pdf,text/*"
            ref={fileInputRef}
            className="hidden"
            onChange={handleFileUpload}
          />

          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type message or paste Drive content..."
            className="flex-1 bg-slate-800 text-white placeholder-slate-500 rounded-full px-4 py-3 focus:outline-none focus:ring-2 focus:ring-indigo-500 border border-slate-700"
            disabled={isLoading}
          />

          <button 
            onClick={handleSend}
            disabled={isLoading || (!inputValue.trim() && attachments.length === 0)}
            className={`p-3 rounded-full transition-all ${
              isLoading || (!inputValue.trim() && attachments.length === 0)
                ? 'bg-slate-800 text-slate-600' 
                : 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20'
            }`}
          >
            {isLoading ? <Loader2 size={20} className="animate-spin" /> : <Send size={20} />}
          </button>
        </div>
      </div>
